source:
/* Programa demostrativo de Kynova — Rapture Edition */
splice adam age;
splice adam laps = 1;
splice eve average;

radio(age);
radio(average);

atlas (age >= 18) {
    diary(average + 5.0);
} ryan {
    diary(0);
}

// Repite tres veces
vita (laps <= 3) {
    diary(laps);
    laps = laps + 1;
}

chapin:
va pisto age;
va pisto laps = 1;
va quetzal average;
clavar(age);
clavar(average);
cabal (age >= 18) {
    shute(average + 5.0);
} sino {
    shute(0);
}
brega (laps <= 3) {
    shute(laps);
    laps = laps + 1;
}

